def main():
 p=argparse.ArgumentParser();p.add_argument('--frame',type=int,required=True);p.add_argument('--version',type=int,default=1);p.add_argument('--base',required=True);p.add_argument('--phase-ref');p.add_argument('--extra',default='');p.add_argument('--short',action='store_true');a=p.parse_args()
 arc=GEN/f'NW{a.frame:02d}-single-v{a.version}';arc.mkdir(exist_ok=True);assert not (arc/'request.json').exists()
