 if a.short:
  prompt=f'Use case: identity-preserve EDIT. Create ONE new animation phase NW{a.frame:02d} by editing IMAGE1. Keep its character, costume, hair, crown, instrument, rear-left camera facing away toward upper-left and whole body size. NEW LEG ACTION: '+a.extra+' Image2 locks original NW character/camera. Image3 is the confirmed PRIMARY art style reference, match its polished clean bright rounded hand painting; no UI. Draw one complete full-body figure native1254x1254 transparent RGBA minimum1024, crown3%/feet97%, two legs and two boots, no extra limbs or shadows, no text or background. Newly draw the requested real walk phase, do not mirror, warp, copy or interpolate. Preserve translucent lavender ribbons and all genuine purple clothing.'
 elif a.extra:prompt+='\n'+a.extra
 req={'tool':'built-in image_gen','configSnapshot':json.loads((ROOT/'config/image-generation.json').read_text(encoding='utf-8')),'actual_request':{'prompt':prompt,'referenced_image_paths':[r.as_posix() for r in refs],'started_at':datetime.now(timezone.utc).isoformat()},'reference_bindings_at_start':[{'path':r.as_posix(),'sha256':hashlib.sha256(r.read_bytes()).hexdigest()} for r in refs]}
 (arc/'prompt.txt').write_bytes(prompt.encode());(arc/'request.json').write_text(json.dumps(req,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({'archive':str(arc),'request':req['actual_request']}))
